window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["wired"]={html:"<div class=\"own-wired\">\n  <header class=\"wr-masthead\">\n    <button class=\"wr-burger\" type=\"button\" aria-label=\"Open menu\" data-wr-menu>\n      <span></span><span></span><span></span>\n    </button>\n    <nav class=\"wr-mast-nav\" aria-label=\"Sections\">\n      <a href=\"#wr-cover\">Operations</a>\n      <a href=\"#wr-grid\">Regions</a>\n      <a href=\"#wr-rows\">Analysis</a>\n    </nav>\n    <a class=\"wr-wordmark\" href=\"#wr-cover\">Northwind</a>\n    <div class=\"wr-mast-right\">\n      <a class=\"wr-sub-link\" href=\"#wr-cta\">Newsletter</a>\n      <a class=\"wr-btn wr-btn-primary wr-btn-sm\" href=\"#wr-cta\">Subscribe</a>\n    </div>\n  </header>\n\n  <main>\n    <section class=\"wr-cover\" id=\"wr-cover\" aria-labelledby=\"wrCoverH\">\n      <p class=\"wr-kicker\">Cover story</p>\n      <h1 class=\"wr-cover-title\" id=\"wrCoverH\">The floor learns to measure itself</h1>\n      <p class=\"wr-cover-lead\">Inside the operations teams replacing overnight spreadsheets with one governed, live board — and what they found when the numbers finally agreed.</p>\n      <div class=\"wr-byline\">\n        <span class=\"wr-avatar\" aria-hidden=\"true\">AR</span>\n        <span class=\"wr-byline-text\"><b>Ada Reyes</b> · Operations desk · Oct 8, 2026</span>\n      </div>\n      <figure class=\"wr-figure\">\n        <div class=\"wr-cover-art\" role=\"img\" aria-label=\"Abstract regional throughput chart, mock illustration\">\n          <svg viewBox=\"0 0 900 420\" preserveAspectRatio=\"none\" aria-hidden=\"true\">\n            <rect width=\"900\" height=\"420\" fill=\"#f5f5f5\"/>\n            <g stroke=\"#e0e0e0\" stroke-width=\"1\">\n              <path d=\"M0 105h900M0 210h900M0 315h900\"/>\n            </g>\n            <g fill=\"#000\">\n              <rect x=\"60\" y=\"250\" width=\"58\" height=\"170\"/>\n              <rect x=\"150\" y=\"200\" width=\"58\" height=\"220\"/>\n              <rect x=\"240\" y=\"286\" width=\"58\" height=\"134\"/>\n              <rect x=\"330\" y=\"120\" width=\"58\" height=\"300\"/>\n              <rect x=\"420\" y=\"168\" width=\"58\" height=\"252\"/>\n              <rect x=\"510\" y=\"70\" width=\"58\" height=\"350\"/>\n              <rect x=\"600\" y=\"140\" width=\"58\" height=\"280\"/>\n              <rect x=\"690\" y=\"96\" width=\"58\" height=\"324\"/>\n            </g>\n            <path d=\"M60 250L150 200L240 286L330 120L420 168L510 70L600 140L690 96\" fill=\"none\" stroke=\"#057dbc\" stroke-width=\"3\"/>\n          </svg>\n        </div>\n        <figcaption>Regional throughput across five shifts. Sample data — showcase only.</figcaption>\n      </figure>\n    </section>\n\n    <section class=\"wr-grid\" id=\"wr-grid\" aria-labelledby=\"wrGridH\">\n      <h2 class=\"wr-grid-head\" id=\"wrGridH\">Also in this issue</h2>\n      <div class=\"wr-grid-2\">\n        <article class=\"wr-card\">\n          <div class=\"wr-card-art\" role=\"img\" aria-label=\"Pie chart of regional mix, mock illustration\">\n            <svg viewBox=\"0 0 400 240\" aria-hidden=\"true\">\n              <rect width=\"400\" height=\"240\" fill=\"#f5f5f5\"/>\n              <circle cx=\"200\" cy=\"120\" r=\"78\" fill=\"none\" stroke=\"#000\" stroke-width=\"34\" stroke-dasharray=\"220 270\"/>\n              <circle cx=\"200\" cy=\"120\" r=\"78\" fill=\"none\" stroke=\"#757575\" stroke-width=\"34\" stroke-dasharray=\"120 370\" stroke-dashoffset=\"-220\"/>\n            </svg>\n          </div>\n          <p class=\"wr-cat\">Analysis</p>\n          <h3 class=\"wr-card-title\">Five regions, one true total</h3>\n          <p class=\"wr-card-lead\">Why reconciling regional dashboards changed how the network plans its shifts.</p>\n        </article>\n        <article class=\"wr-card\">\n          <div class=\"wr-card-art\" role=\"img\" aria-label=\"Line chart of on-time rate, mock illustration\">\n            <svg viewBox=\"0 0 400 240\" aria-hidden=\"true\">\n              <rect width=\"400\" height=\"240\" fill=\"#f5f5f5\"/>\n              <path d=\"M20 190L90 170L160 176L230 120L300 132L380 74\" fill=\"none\" stroke=\"#000\" stroke-width=\"3\"/>\n              <path d=\"M20 190L90 170L160 176L230 120L300 132L380 74V240H20Z\" fill=\"none\"/>\n            </svg>\n          </div>\n          <p class=\"wr-cat\">Dispatch</p>\n          <h3 class=\"wr-card-title\">The on-time rate stops lying</h3>\n          <p class=\"wr-card-lead\">A new definition of \"on time\" surfaced the real bottlenecks on the night shift.</p>\n        </article>\n      </div>\n    </section>\n\n    <section class=\"wr-rows-sec\" id=\"wr-rows\" aria-labelledby=\"wrRowsH\">\n      <h2 class=\"wr-rows-head\" id=\"wrRowsH\">More from the desk</h2>\n      <ol class=\"wr-rows\">\n        <li class=\"wr-row\">\n          <span class=\"wr-row-num\">01</span>\n          <div class=\"wr-row-body\">\n            <p class=\"wr-cat\">Field notes</p>\n            <h3 class=\"wr-row-title\">The supervisors who stopped rebuilding the report</h3>\n            <p class=\"wr-row-meta\">Ada Reyes · 6 min read</p>\n          </div>\n        </li>\n        <li class=\"wr-row\">\n          <span class=\"wr-row-num\">02</span>\n          <div class=\"wr-row-body\">\n            <p class=\"wr-cat\">Method</p>\n            <h3 class=\"wr-row-title\">How a governed model ends the spreadsheet wars</h3>\n            <p class=\"wr-row-meta\">Leo Tanaka · 9 min read</p>\n          </div>\n        </li>\n        <li class=\"wr-row\">\n          <span class=\"wr-row-num\">03</span>\n          <div class=\"wr-row-body\">\n            <p class=\"wr-cat\">Interview</p>\n            <h3 class=\"wr-row-title\">\"We shipped a board in an afternoon\"</h3>\n            <p class=\"wr-row-meta\">Mara Okafor · 5 min read</p>\n          </div>\n        </li>\n        <li class=\"wr-row\">\n          <span class=\"wr-row-num\">04</span>\n          <div class=\"wr-row-body\">\n            <p class=\"wr-cat\">Data</p>\n            <h3 class=\"wr-row-title\">Throughput, quarter over quarter, in one table</h3>\n            <p class=\"wr-row-meta\">Ada Reyes · 4 min read</p>\n          </div>\n        </li>\n      </ol>\n    </section>\n\n    <section class=\"wr-cta\" id=\"wr-cta\" aria-labelledby=\"wrCtaH\">\n      <div class=\"wr-cta-copy\">\n        <p class=\"wr-kicker wr-kicker-inv\">Northwind weekly</p>\n        <h2 class=\"wr-cta-title\" id=\"wrCtaH\">The operations desk, in your inbox</h2>\n        <p class=\"wr-cta-lead\">One long read and one data note every Thursday. No marketing.</p>\n      </div>\n      <form class=\"wr-form\" data-wr-form novalidate>\n        <label class=\"wr-field\">\n          <span class=\"wr-field-label\">Email address</span>\n          <input id=\"wrEmail\" type=\"email\" name=\"email\" placeholder=\"you@team.co\" autocomplete=\"email\" required>\n        </label>\n        <button class=\"wr-btn wr-btn-primary\" type=\"submit\">Subscribe</button>\n        <p class=\"wr-form-note\" data-wr-note role=\"status\" aria-live=\"polite\"></p>\n      </form>\n    </section>\n  </main>\n\n  <footer class=\"wr-footer\">\n    <div class=\"wr-foot-top\">\n      <a class=\"wr-wordmark wr-wordmark-foot\" href=\"#wr-cover\">Northwind</a>\n      <p class=\"wr-foot-tag\">Operations analytics, reported.</p>\n    </div>\n    <div class=\"wr-foot-cols\">\n      <nav class=\"wr-foot-col\" aria-label=\"Sections\">\n        <h4>Sections</h4>\n        <a href=\"#wr-cover\">Operations</a>\n        <a href=\"#wr-grid\">Regions</a>\n        <a href=\"#wr-rows\">Analysis</a>\n      </nav>\n      <nav class=\"wr-foot-col\" aria-label=\"Company\">\n        <h4>Company</h4>\n        <a href=\"#\">About</a>\n        <a href=\"#\">Careers</a>\n        <a href=\"#\">Contact</a>\n      </nav>\n      <nav class=\"wr-foot-col\" aria-label=\"Legal\">\n        <h4>Legal</h4>\n        <a href=\"#\">Privacy</a>\n        <a href=\"#\">Terms</a>\n        <a href=\"#\">Licensing</a>\n      </nav>\n    </div>\n    <p class=\"wr-foot-base\">Sample data — showcase only · &copy; 2026 Northwind</p>\n  </footer>\n</div>\n",css:"/* ══ WIRED — own layout for showcase.html ══════════════════════════════════\n   The strict editorial black-and-white duet from DESIGN.md: pure #000 ink,\n   #fff canvas, no chromatic accent except the inline link blue #057dbc, three\n   faces (WiredDisplay serif display → Playfair Display substitute; BreveText\n   serif body → Lora; Apercu sans → Inter), every corner square (rounded.none),\n   hairline #e0e0e0 dividers for the only elevation. Scoped under `.own-wired`. */\n\n.own-wired {\n  --wr-ink: #000000;\n  --wr-ink-soft: #1a1a1a;\n  --wr-body: #757575;\n  --wr-hairline: #e0e0e0;\n  --wr-canvas: #ffffff;\n  --wr-canvas-soft: #f5f5f5;\n  --wr-link: #057dbc;\n  --wr-display: 'WiredDisplay', 'Playfair Display', 'Times New Roman', Georgia, serif;\n  --wr-serif: 'BreveText', 'Lora', Georgia, 'Times New Roman', serif;\n  --wr-sans: 'Apercu', 'Inter', 'Helvetica Neue', Helvetica, Arial, sans-serif;\n  --wr-gut: clamp(20px, 4cqi, 48px);\n\n  position: relative;\n  background: var(--wr-canvas);\n  color: var(--wr-ink);\n  font-family: var(--wr-sans);\n  font-size: 17px;\n  line-height: 1.5;\n  -webkit-font-smoothing: antialiased;\n  text-align: left;\n  border-radius: 13px;\n}\n\n.own-wired *, .own-wired *::before, .own-wired *::after { box-sizing: border-box; }\n.own-wired p { margin: 0; }\n.own-wired a { color: inherit; text-decoration: none; }\n.own-wired :focus-visible { outline: 3px solid var(--wr-ink); outline-offset: 2px; }\n.own-wired .wr-kicker {\n  font-family: var(--wr-sans); font-size: 14px; font-weight: 700; letter-spacing: .4px;\n  text-transform: uppercase; margin-bottom: 14px;\n}\n.own-wired .wr-kicker-inv { color: #fff; }\n.own-wired .wr-cat {\n  font-family: var(--wr-sans); font-size: 13px; font-weight: 700; letter-spacing: .4px;\n  text-transform: uppercase; color: var(--wr-ink); margin-bottom: 10px;\n}\n\n/* ── buttons ─────────────────────────────────────────────────────────────── */\n.own-wired .wr-btn {\n  display: inline-flex; align-items: center; justify-content: center;\n  font-family: var(--wr-sans); font-size: 16px; font-weight: 700; letter-spacing: .3px;\n  padding: 12px 20px; border: 1px solid var(--wr-ink); border-radius: 0;\n  cursor: pointer; transition: background-color .18s ease, color .18s ease;\n}\n.own-wired .wr-btn-sm { padding: 8px 14px; font-size: 14px; }\n.own-wired .wr-btn-primary { background: var(--wr-ink); color: #fff; }\n.own-wired .wr-btn-primary:hover { background: var(--wr-ink-soft); }\n\n/* ── masthead ────────────────────────────────────────────────────────────── */\n.own-wired .wr-masthead {\n  position: sticky; top: 68px; z-index: 30;\n  display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; gap: 16px;\n  padding: 12px var(--wr-gut); background: var(--wr-canvas);\n  border-bottom: 1px solid var(--wr-ink);\n}\n.own-wired .wr-mast-nav { display: flex; align-items: center; gap: 20px; }\n.own-wired .wr-mast-nav a { font-size: 14px; font-weight: 700; letter-spacing: .4px; }\n.own-wired .wr-mast-nav a:hover { text-decoration: underline; text-underline-offset: 4px; }\n.own-wired .wr-wordmark {\n  font-family: var(--wr-display); font-size: 30px; font-weight: 400; letter-spacing: .5px;\n  text-align: center; line-height: 1; padding-bottom: 4px; border-bottom: 3px solid var(--wr-ink);\n}\n.own-wired .wr-mast-right { display: flex; align-items: center; justify-content: flex-end; gap: 16px; }\n.own-wired .wr-sub-link { font-size: 14px; font-weight: 700; letter-spacing: .4px; }\n.own-wired .wr-sub-link:hover { text-decoration: underline; text-underline-offset: 4px; }\n.own-wired .wr-burger { display: none; flex-direction: column; gap: 4px; width: 32px; height: 32px; align-items: center; justify-content: center; background: none; border: 0; cursor: pointer; }\n.own-wired .wr-burger span { display: block; width: 22px; height: 2px; background: var(--wr-ink); }\n\n/* ── cover story ─────────────────────────────────────────────────────────── */\n.own-wired .wr-cover { padding: 48px var(--wr-gut) 40px; max-width: 1000px; margin: 0 auto; }\n.own-wired .wr-cover-title {\n  font-family: var(--wr-display); font-size: clamp(40px, 7cqi, 64px); font-weight: 400;\n  line-height: .95; letter-spacing: -.5px; max-width: 18ch;\n}\n.own-wired .wr-cover-lead {\n  font-family: var(--wr-serif); font-size: 19px; line-height: 1.47; letter-spacing: .1px;\n  color: var(--wr-ink); max-width: 60ch; margin-top: 22px;\n}\n.own-wired .wr-byline { display: flex; align-items: center; gap: 12px; margin-top: 24px; padding-bottom: 32px; border-bottom: 1px solid var(--wr-hairline); }\n.own-wired .wr-avatar {\n  display: grid; place-items: center; width: 28px; height: 28px; border-radius: 9999px;\n  background: var(--wr-ink); color: #fff; font-family: var(--wr-sans); font-size: 11px; font-weight: 700;\n}\n.own-wired .wr-byline-text { font-family: var(--wr-serif); font-size: 13px; font-weight: 700; color: var(--wr-ink); }\n.own-wired .wr-figure { margin: 32px 0 0; }\n.own-wired .wr-cover-art { border: 1px solid var(--wr-hairline); }\n.own-wired .wr-cover-art svg { display: block; width: 100%; height: auto; aspect-ratio: 900 / 420; }\n.own-wired .wr-figure figcaption {\n  font-family: var(--wr-sans); font-size: 12px; line-height: 1.33; color: var(--wr-body);\n  margin-top: 10px; max-width: 70ch;\n}\n\n/* ── secondary grid ──────────────────────────────────────────────────────── */\n.own-wired .wr-grid { padding: 48px var(--wr-gut) 8px; max-width: 1200px; margin: 0 auto; }\n.own-wired .wr-grid-head, .own-wired .wr-rows-head {\n  font-family: var(--wr-sans); font-size: 14px; font-weight: 700; letter-spacing: .4px;\n  text-transform: uppercase; padding-bottom: 12px; margin-bottom: 24px;\n  border-bottom: 1px solid var(--wr-ink);\n}\n.own-wired .wr-grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 32px; }\n.own-wired .wr-card-art { border: 1px solid var(--wr-hairline); margin-bottom: 18px; }\n.own-wired .wr-card-art svg { display: block; width: 100%; height: auto; aspect-ratio: 400 / 240; }\n.own-wired .wr-card-title { font-family: var(--wr-display); font-size: 26px; font-weight: 400; line-height: 1.1; }\n.own-wired .wr-card-lead { font-family: var(--wr-serif); font-size: 16px; line-height: 1.5; color: #333; margin-top: 10px; }\n\n/* ── story rows ──────────────────────────────────────────────────────────── */\n.own-wired .wr-rows-sec { padding: 48px var(--wr-gut) 8px; max-width: 1000px; margin: 0 auto; }\n.own-wired .wr-rows { list-style: none; margin: 0; padding: 0; }\n.own-wired .wr-row {\n  display: grid; grid-template-columns: 64px 1fr; gap: 24px; align-items: baseline;\n  padding: 18px 0; border-bottom: 1px solid var(--wr-hairline);\n}\n.own-wired .wr-row-num { font-family: var(--wr-display); font-size: 26px; color: var(--wr-body); }\n.own-wired .wr-row-title { font-family: var(--wr-sans); font-size: 17px; font-weight: 700; line-height: 1.3; letter-spacing: -.14px; }\n.own-wired .wr-row-title:hover { text-decoration: underline; text-underline-offset: 4px; }\n.own-wired .wr-row-meta { font-family: var(--wr-sans); font-size: 14px; color: var(--wr-body); margin-top: 6px; }\n\n/* ── subscribe CTA ───────────────────────────────────────────────────────── */\n.own-wired .wr-cta {\n  display: grid; grid-template-columns: 1.2fr 1fr; gap: 40px; align-items: center;\n  margin-top: 48px; padding: 48px var(--wr-gut); background: var(--wr-ink); color: #fff;\n}\n.own-wired .wr-cta-title { font-family: var(--wr-display); font-size: clamp(28px, 4cqi, 44px); font-weight: 400; line-height: 1.05; letter-spacing: -.4px; }\n.own-wired .wr-cta-lead { font-family: var(--wr-serif); font-size: 18px; line-height: 1.5; color: #c9c9c9; margin-top: 14px; }\n.own-wired .wr-form { display: flex; flex-direction: column; gap: 14px; }\n.own-wired .wr-field { display: flex; flex-direction: column; gap: 8px; }\n.own-wired .wr-field-label { font-size: 14px; font-weight: 700; letter-spacing: .4px; }\n.own-wired .wr-form input {\n  font-family: var(--wr-sans); font-size: 16px; padding: 12px 16px;\n  background: transparent; color: #fff; border: 1px solid rgba(255,255,255,.4); border-radius: 0;\n}\n.own-wired .wr-form input::placeholder { color: #9a9a9a; }\n.own-wired .wr-form input:focus { outline: none; border-color: #fff; }\n.own-wired .wr-form .wr-btn-primary { background: #fff; color: var(--wr-ink); border-color: #fff; }\n.own-wired .wr-form .wr-btn-primary:hover { background: #e6e6e6; }\n.own-wired .wr-form-note { font-family: var(--wr-sans); font-size: 14px; min-height: 20px; color: #c9c9c9; }\n\n/* ── footer ──────────────────────────────────────────────────────────────── */\n.own-wired .wr-footer { background: var(--wr-ink); color: #fff; padding: 48px var(--wr-gut); }\n.own-wired .wr-foot-top { padding-bottom: 24px; border-bottom: 1px solid rgba(255,255,255,.22); }\n.own-wired .wr-wordmark-foot { display: inline-block; color: #fff; border-color: #fff; }\n.own-wired .wr-foot-tag { font-family: var(--wr-serif); font-size: 15px; color: #b8b8b8; margin-top: 14px; }\n.own-wired .wr-foot-cols { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; padding: 32px 0; }\n.own-wired .wr-foot-col { display: flex; flex-direction: column; gap: 10px; }\n.own-wired .wr-foot-col h4 { font-size: 14px; font-weight: 700; letter-spacing: .4px; margin-bottom: 4px; }\n.own-wired .wr-foot-col a { font-size: 14px; color: #b8b8b8; }\n.own-wired .wr-foot-col a:hover { color: #fff; text-decoration: underline; text-underline-offset: 4px; }\n.own-wired .wr-foot-base { font-size: 12px; color: #8f8f8f; padding-top: 20px; border-top: 1px solid rgba(255,255,255,.22); }\n\n/* ── responsive — @container frame ───────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-wired .wr-cover { padding-top: 40px; }\n  .own-wired .wr-cta { grid-template-columns: 1fr; gap: 28px; }\n}\n@container frame (max-width: 760px) {\n  .own-wired .wr-masthead { grid-template-columns: auto 1fr auto; }\n  .own-wired .wr-mast-nav { display: none; }\n  .own-wired .wr-mast-nav.wr-open {\n    display: flex; flex-direction: column; align-items: flex-start; gap: 14px;\n    position: absolute; top: 100%; left: 0; right: 0; padding: 18px var(--wr-gut);\n    background: var(--wr-canvas); border-bottom: 1px solid var(--wr-ink);\n  }\n  .own-wired .wr-burger { display: flex; }\n  .own-wired .wr-sub-link { display: none; }\n  .own-wired .wr-grid-2 { grid-template-columns: 1fr; }\n  .own-wired .wr-cover-title { letter-spacing: -.3px; }\n}\n@container frame (max-width: 430px) {\n  .own-wired .wr-wordmark { font-size: 24px; border-bottom-width: 2px; }\n  .own-wired .wr-row { grid-template-columns: 40px 1fr; gap: 14px; }\n  .own-wired .wr-row-num { font-size: 20px; }\n  .own-wired .wr-foot-cols { grid-template-columns: 1fr; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .own-wired .wr-btn { transition: none; }\n}\n"};
/* ══ WIRED — own layout behaviour for showcase.html ════════════════════════
   Registers window.OWN_LAYOUTS['wired'].init(root). Opens/closes the mobile
   section menu and runs the newsletter form's local, offline validation.
   init returns a cleanup that detaches every listener. Query only in `root`. */

(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  OWN['wired'] = {
    init: function (root) {
      var cleanups = [];

      function on(el, ev, fn) { el.addEventListener(ev, fn); cleanups.push(function () { el.removeEventListener(ev, fn); }); }

      var burger = root.querySelector('[data-wr-menu]');
      var nav = root.querySelector('.wr-mast-nav');
      if (burger && nav) {
        on(burger, 'click', function () {
          var open = nav.classList.toggle('wr-open');
          burger.setAttribute('aria-expanded', open ? 'true' : 'false');
        });
      }

      var form = root.querySelector('[data-wr-form]');
      var note = root.querySelector('[data-wr-note]');
      if (form && note) {
        on(form, 'submit', function (e) {
          e.preventDefault();
          var input = form.querySelector('input[type="email"]');
          var val = input ? input.value.trim() : '';
          if (!val) { note.textContent = 'Enter an email address to subscribe.'; return; }
          if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(val)) { note.textContent = 'That doesn\u2019t look like a valid email.'; return; }
          note.textContent = 'Subscribed. Check your inbox to confirm.';
          form.reset();
        });
      }

      return function cleanup() {
        cleanups.forEach(function (fn) { try { fn(); } catch (e) { /* ignore */ } });
      };
    }
  };
})();
